javascript:
frappe.query_reports["Employee Expense Report"] = {
    filters: [
        {
            fieldname: "company",
            label: __("Company"),
            fieldtype: "Link",
            options: "Company",
            default: frappe.defaults.get_user_default("Company")
        },

        {
            fieldname: "from_date",
            label: __("From Date"),
            fieldtype: "Date",
            default: frappe.datetime.add_months(
                frappe.datetime.get_today(),
                -1
            )
        },

        {
            fieldname: "to_date",
            label: __("To Date"),
            fieldtype: "Date",
            default: frappe.datetime.get_today()
        },

        {
            fieldname: "employee",
            label: __("Employee"),
            fieldtype: "Link",
            options: "Employee"
        },

        {
            fieldname: "department",
            label: __("Department"),
            fieldtype: "Link",
            options: "Department"
        },

        {
            fieldname: "branch",
            label: __("Branch"),
            fieldtype: "Link",
            options: "Branch"
        },

        {
            fieldname: "expense_claim",
            label: __("Expense Claim"),
            fieldtype: "Link",
            options: "Expense Claim"
        },

        {
            fieldname: "expense_type",
            label: __("Expense Type"),
            fieldtype: "Link",
            options: "Expense Claim Type"
        },

        {
            fieldname: "cost_center",
            label: __("Cost Center"),
            fieldtype: "Link",
            options: "Cost Center"
        },

        {
            fieldname: "approval_status",
            label: __("Approval Status"),
            fieldtype: "Select",
            options: "\nDraft\nApproved\nRejected"
        }
    ],

    formatter: function(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);

        if (
            column.fieldname === "receipt_attachment" &&
            data &&
            data.receipt_attachment
        ) {
            const url = encodeURI(data.receipt_attachment);

            return `
                <a
                    href="${url}"
                    target="_blank"
                    rel="noopener noreferrer"
                >
                    View Receipt
                </a>
            `;
        }

        return value;
    }
};
